import React, { useState } from "react";
import axios from "axios";

export default function Register() {
  const [form, setForm] = useState({
    studentNumber: "",
    email: "",
    name: "",
    password: "",
  });

  const [qrUrl, setQrUrl] = useState(null);
  const [message, setMessage] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage("");
    setQrUrl(null);

    try {
      const res = await axios.post("http://localhost:4000/api/auth/register", form);

      // If backend sends QR code after registration
      if (res.data.totpQr) {
        setQrUrl(res.data.totpQr);
        setMessage("Registration successful! Scan the QR code with your authenticator app.");
      } else {
        setMessage("Registration successful!");
      }

    } catch (err) {
      console.error(err);
      setMessage(err.response?.data?.error || "Registration failed");
    }
  };

  return (
    <div>
      <h2>Register</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          name="studentNumber"
          placeholder="Student Number"
          value={form.studentNumber}
          onChange={handleChange}
        />
        <input
          type="email"
          name="email"
          placeholder="Email"
          value={form.email}
          onChange={handleChange}
        />
        <input
          type="text"
          name="name"
          placeholder="Name"
          value={form.name}
          onChange={handleChange}
        />
        <input
          type="password"
          name="password"
          placeholder="Password"
          value={form.password}
          onChange={handleChange}
        />
        <button type="submit">Register</button>
      </form>

      {message && <p>{message}</p>}

      {qrUrl && (
        <div>
          <h3>Scan this QR code in your Authenticator app:</h3>
          <img src={qrUrl} alt="TOTP QR Code" />
        </div>
      )}
    </div>
  );
}
